// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(this) && recipient != address(0) && recipient != address(c));
        uint256 initialBalance = address(c).balance;
        vm.deal(address(c), 1 ether);
        initialBalance = address(c).balance;

        // Attempt to withdrawAll; note: send may revert silently, transfer will revert on failure
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));

        uint256 finalBalance = address(c).balance;
        // If the call succeeded (transfer or send worked), balance should be 0.
        // If send failed, balance remains unchanged.
        if (success) {
            assertTrue(finalBalance == 0);
        } else {
            assertTrue(finalBalance == initialBalance);
        }
    }
}

